-- Local synthetic fixture only. Never run on hosted data; no provider request is made.
begin;
create temporary table csf(owner_id uuid,viewer_id uuid,wid uuid,sid uuid,request_id uuid,second_request uuid,profile_id uuid,test_id uuid,content_id uuid);
insert into csf values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null);
insert into auth.users(id) select owner_id from csf union all select viewer_id from csf;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,owner_id,'Channel specialist fixture' from csf;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,owner_id,'owner' from csf union all select wid,viewer_id,'viewer' from csf;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Specialist site','native_business','business','active',owner_id from csf;
update csf set content_id=(select id from bizoveya_private.agent_definitions where kind='content' order by id limit 1);
create function pg_temp.csexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on csf to authenticated,service_role;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile_id,'channel-specialist-fixture',1,1 from csf;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile_id,1,'{"name":"Fixture","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic specialist fixture' from csf;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile_id,1,'platform-gemini',1 from csf;
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,input_tokens,output_tokens,reason,finished_at) select test_id,profile_id,1,'platform-gemini',1,gen_random_uuid(),'passed','response_matched',1,1,'Synthetic only',clock_timestamp() from csf;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile_id,1,1,jsonb_build_object('enabled',true,'inputRateMicros',0,'outputRateMicros',0,'requestFeeMicros',0,'dailyLimitMicros',10000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/synthetic','reviewed',true),'Synthetic only' from csf;
update bizoveya_private.agent_versions set document=jsonb_set(document,'{modelTier}','"economical"') where agent_id=(select content_id from csf) and version=1;
update bizoveya_private.agent_definitions set preview_version=1 where id=(select content_id from csf);
insert into bizoveya_private.agent_checks(agent_id,version) select content_id,1 from csf on conflict do nothing;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select content_id,1,profile_id,1,1,test_id,1,true,'Synthetic specialist binding' from csf;
create temporary table csr as select jsonb_build_object('enabled',true,'assignments',jsonb_build_array(jsonb_build_object('channel','blog','agentId',content_id,'agentVersion',1),jsonb_build_object('channel','pinterest','agentId',content_id,'agentVersion',1),jsonb_build_object('channel','linkedin','agentId',content_id,'agentVersion',1))) document from csf;grant all on csr to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from csf),true);
select public.bz_save_site_channel_specialists(wid,sid,jsonb_build_object('document',csr.document,'expectedVersion',0,'reason','Enable reviewed private channel specialists.','reviewed',true)) from csf,csr;
select public.bz_save_site_channel_specialists(wid,sid,jsonb_build_object('document',csr.document,'expectedVersion',0,'reason','Enable reviewed private channel specialists.','reviewed',true)) from csf,csr;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','request','id',request_id,'instruction','Prepare private Blog and Pinterest drafts.','channels',jsonb_build_array('blog','pinterest'),'reviewed',true,'inputMode','text')) from csf;
select public.bz_delegate_agency_request_specialists(wid,sid,jsonb_build_object('id',request_id,'expectedVersion',1,'reason','Delegate only to the reviewed private channel roster.','reviewed',true)) from csf;
select public.bz_delegate_agency_request_specialists(wid,sid,jsonb_build_object('id',request_id,'expectedVersion',1,'reason','Delegate only to the reviewed private channel roster.','reviewed',true)) from csf;
select pg_temp.csexpect(format('select public.bz_delegate_agency_request_specialists(%L,%L,%L)',wid,sid,jsonb_build_object('id',request_id,'expectedVersion',2,'reason','Changed duplicate delegation reason.','reviewed',true)),'bz_conflict') from csf;
reset role;
do $$declare j jsonb;begin j:=bizoveya_private.agency_json((select request_id from csf));if j#>>'{channelDelegation,rosterVersion}'<>'1' or jsonb_array_length(j#>'{channelDelegation,assignments}')<>2 or j#>>'{channelDelegation,assignments,0,channel}'<>'blog' or j#>>'{channelDelegation,assignments,1,channel}'<>'pinterest' or (select version from bizoveya_private.agency_records where id=(select request_id from csf))<>2 or (select count(*) from bizoveya_private.agency_channel_delegations)<>1 then raise exception 'Specialist delegation projection or retry mismatch';end if;if exists(select 1 from bizoveya_private.generation_runs) then raise exception 'Specialist delegation started generation';end if;end;$$;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from csf),true);
select public.bz_save_site_channel_specialists(wid,sid,jsonb_build_object('document',jsonb_set(csr.document,'{enabled}','false'),'expectedVersion',1,'reason','Pause all new specialist delegation.','reviewed',true)) from csf,csr;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','request','id',second_request,'instruction','Prepare a private LinkedIn draft.','channels',jsonb_build_array('linkedin'),'reviewed',true,'inputMode','text')) from csf;
select pg_temp.csexpect(format('select public.bz_delegate_agency_request_specialists(%L,%L,%L)',wid,sid,jsonb_build_object('id',second_request,'expectedVersion',1,'reason','Paused roster must reject this delegation.','reviewed',true)),'bz_channel_specialists_paused') from csf;
select set_config('request.jwt.claim.sub',(select viewer_id::text from csf),true);
select public.bz_site_channel_specialists(wid,sid) from csf;
select pg_temp.csexpect(format('select public.bz_save_site_channel_specialists(%L,%L,%L)',wid,sid,jsonb_build_object('document',csr.document,'expectedVersion',2,'reason','Viewer cannot enable specialists.','reviewed',true)),'bz_forbidden') from csf,csr;
select pg_temp.csexpect('select * from bizoveya_private.site_channel_specialists','permission denied');
reset role;
select pg_temp.csexpect('update bizoveya_private.agency_channel_delegations set reason=''forged''','bz_immutable_agency_handoff');
delete from public.bizoveya_sites where id=(select sid from csf);
do $$begin if exists(select 1 from bizoveya_private.site_channel_specialists) or exists(select 1 from bizoveya_private.site_channel_specialist_revisions) or exists(select 1 from bizoveya_private.agency_channel_delegations) then raise exception 'Specialist site cascade failed';end if;end;$$;
rollback;
